        assert!(upload.args.iter().all(|arg| !arg.contains('*')), "{:?}", upload.args);
        assert_eq!(
            &upload.args[upload.args.len() - 2..],
            ["/tmp/out/my_pkg-1.2.3-py3-none-any.whl", "/tmp/out/my_pkg-1.2.3.tar.gz",]
