35	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
36	/// experimental and hides yanked releases, and an unreachable index and a
37	/// missing project both look like "no versions found" to it. The index itself
38	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
39	/// so observation goes straight to `https://pypi.org/simple/<project>/`
40	/// (or the configured private index) over `curl`, never through `pip`.
41	pub(super) const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
42	
43	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
44	/// the legacy HTML page a bare GET would otherwise serve.
45	pub(super) const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
46	
47	/// The project's simple-index URL: the configured private index if one is
48	/// bound (already https-validated in `binding.rs`), else the public default.
49	pub(super) fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
50	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
51	    let project = normalize_pypi_project_name(package_name);
52	    format!("{}/{project}/", base.trim_end_matches('/'))
53	}
54	
55	/// The version segment of a simple-index filename, or `None` for an extension
56	/// this parser does not recognize (a legacy installer, say).
57	pub(super) fn pypi_simple_file_version(filename: &str) -> Option<&str> {
58	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
59	}
60	
61	/// Whether a simple-index file's filename names exactly the requested version.
62	pub(super) fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
63	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
64	        Version::parse(candidate, version.grammar())
65	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
66	    })
67	}
68	
69	/// Classifies a parsed 200 body: the matching file's yank status decides the
70	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
71	/// release is not the version this intent authorized, so it fails closed.
72	pub(super) fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
73	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
74	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
75	    };
76	    let matching = index
77	        .files
78	        .iter()
79	        .filter(|file| pypi_simple_file_matches(file, version));
80	    let mut matched = false;
81	    for file in matching {
82	        if file.is_yanked() {
83	            return settled(ProviderObservationV1::Absent);
84	        }
85	        matched = true;
86	    }
87	    if !matched {
88	        return settled(ProviderObservationV1::Absent);
89	    }
90	    settled(exact_version(version))
91	}
