179	pub(super) fn classify_pypi_files(output: &CommandOutput, version: &Version) -> Attempt<PypiRemote> {
180	    classify_pypi_status(
181	        output,
182	        |body| classify_pypi_files_body(body, version),
183	        PypiRemote::Absent,
184	        PypiRemote::Indeterminate,
185	    )
186	}
