188	impl PypiRegistry {
189	    /// One `curl` of the project's simple index; `Err` when the command could not run at all.
190	    fn fetch_once(
191	        context: &ProviderContext<'_>,
192	        operation: &RegistryPublishOperation,
193	    ) -> Result<Result<CommandOutput, policy::CommandUnavailable>, GraphError> {
194	        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
195	        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
196	        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
